1	// What a policy covers, and what it pays out. The mirror image of pricing.ts:
2	// that module answers what the customer pays us, this one answers what we pay
3	// the customer. Both are asked by claim-office.ts, which knows the order the
4	// questions come in; neither knows anything about scenarios or steps.
5	
6	import { type Item, type KnownItemType } from "./pricing.js";
7	import { claimRejection } from "./rejection.js";
8	
9	export interface Damage {
10	  itemType: string;
11	  amount: number;
12	}
13	
14	// What an item is insured FOR, as opposed to what insuring it costs. Payout
15	// caps are derived from these; premiums are not.
16	//
17	// Deliberately typed as a TOTAL Record over KnownItemType, and deliberately
18	// looked up UNGUARDED below, unlike the price list in pricing.ts. Two reasons,
19	// and the type is the load-bearing one:
20	//
21	//  - Adding a type to pricing.ts's BASE_PREMIUM_BY_TYPE without adding it here
22	//    is a compile error, so the two tables cannot drift apart silently. The
23	//    price list needs its runtime guard because item types arrive from parsed
24	//    JSON and can be values TypeScript never saw; this table is only ever
25	//    indexed by a type that already survived that guard.
26	//  - A quote is rejected before any policy exists, so no unknown type can
27	//    reach a cap. A throw here would be a branch no test could turn red.
28	const INSURANCE_VALUE_BY_TYPE: Record<KnownItemType, number> = {
29	  sword: 1000,
30	  amulet: 600,
31	  staff: 800,
32	  potion: 400,
33	  rune: 250,
34	  moonstone: 250,
35	};
36	
37	const insuranceSumOf = (items: Item[]): number =>
38	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
39	
40	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
41	
42	// A policy pays out at most twice what its items are insured for. Premium
43	// modifiers — curses, enchantments, block discounts — shift what the policy
44	// COSTS and never what it COVERS, so the cap reads insurance values only.
45	export const capFor = (items: Item[]): number =>
46	  CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items);
47	
48	// What a claim actually pays, once the policy's own limit is consulted. The
49	// cap is a running total: a policy pays out at most twice its insurance sum
50	// ACROSS all its claims, so each settlement both reads the cap left to it and
51	// reports what remains for the next one.
52	//
53	// Lives here beside capFor rather than in the orchestrator: establishing the
54	// limit and enforcing it are one rule, and claim-office.ts is only meant to
55	// know the order the questions come in, not the answers.
56	export interface Settlement {
57	  payout: number;
58	  remainingCap: number;
59	}
60	
61	export const settleClaim = (
62	  grossPayout: number,
63	  remainingCap: number,
64	): Settlement => {
65	  const payout = Math.min(grossPayout, remainingCap);
66	  return { payout, remainingCap: remainingCap - payout };
67	};
68	
69	const DEDUCTIBLE_PER_DAMAGE = 100;
70	
71	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
72	const HALF_REIMBURSEMENT_SHARE = 0.5;
73	
74	const FULL_REIMBURSEMENT_SHARE = 1;
75	
76	// Named for the clause it gates rather than for a degree of enchantment:
77	// pricing.ts has its own, LOWER enchantment threshold (>= 5, a premium
78	// surcharge), and the two are easy to confuse when both read as adjectives.
79	const qualifiesForHalfReimbursement = (item: Item): boolean =>
80	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
81	
82	// The reimbursement clauses in the order the MHPCO applies them: the FIRST
83	// matching clause decides the share, later ones never override it. Order is
84	// the whole content of the rule, so the list is written out even though the
85	// dragon clause and the default agree — see the note below.
86	//
87	// Half reimbursement: the MHPCO holds that a strongly enchanted item's magic
88	// bears part of its own misfortune.
89	const REIMBURSEMENT_CLAUSES: {
90	  applies: (item: Item) => boolean;
91	  share: number;
92	}[] = [
93	  { applies: qualifiesForHalfReimbursement, share: HALF_REIMBURSEMENT_SHARE },
94	  { applies: () => true, share: FULL_REIMBURSEMENT_SHARE },
95	];
96	
97	// Deliberately ABSENT: the spec's "dragon material => full reimbursement"
98	// clause, which would sit above the half clause. It is unwritten because it is
99	// untestable from the spec's examples — full reimbursement is also the default,
100	// so every dragon example yields the same payout with or without it. The one
101	// case that WOULD distinguish the two orderings, a dragon item with
102	// enchantment >= 8, is fixed by example at HALF (see the enchantment-9 test),
103	// which is the opposite of what a dragon-first clause would pay. So the spec's
104	// own examples contradict placing a dragon clause first, and no example
105	// justifies placing it anywhere else. Adding one here would be guesswork
106	// dressed as fidelity; `material` stays unread until an example forces it.
107	
108	const reimbursementShareFor = (item: Item): number =>
109	  REIMBURSEMENT_CLAUSES.find(({ applies }) => applies(item))?.share ??
110	  FULL_REIMBURSEMENT_SHARE;
111	
112	const reimbursementFor = (item: Item, damage: Damage): number =>
113	  damage.amount * reimbursementShareFor(item);
114	
115	// The customer bears the first 100 G of each damage entry separately, so two
116	// damaged swords carry two deductibles rather than one. The deductible comes
117	// off AFTER the reimbursement clauses have reduced the amount.
118	//
119	// Named for the single subtraction it performs, not for the final payout: this
120	// result is not floored at zero, and the policy's remaining cap is applied
121	// later by settleClaim rather than here. Flooring is still it.todo() in the
122	// spec ("exhausts the cap across successive claims"); until an example forces
123	// it, the name must not claim a settlement this does not compute.
124	const netOfDeductible = (item: Item, damage: Damage): number =>
125	  reimbursementFor(item, damage) - DEDUCTIBLE_PER_DAMAGE;
126	
127	// Two different ways a damage can fail to find an insured item, which the
128	// MHPCO rejects for two different reasons. A policy that insures no amulet at
129	// all does not "cover more amulet damages than it insures" — it covers none,
130	// and the claim names an item the customer never brought in. Telling them
131	// apart needs the policy's ORIGINAL items, not just the ones still unclaimed.
132	const uninsuredTypeError = (itemType: string): Error =>
133	  claimRejection(`names a ${itemType}, which the policy does not insure`);
134	
135	const overClaimedTypeError = (itemType: string): Error =>
136	  claimRejection(`covers more ${itemType} damages than the policy insures`);
137	
138	const unmatchedDamageError = (insured: Item[], itemType: string): Error =>
139	  insured.some((item) => item.type === itemType)
140	    ? overClaimedTypeError(itemType)
141	    : uninsuredTypeError(itemType);
142	
143	// Which insured item a damage entry is paid against. A damage names its item
144	// by type only, so the first insured item of that type answers it — but each
145	// insured item is damaged at most once per claim, so a matched item is removed
146	// from those still available. Two sword damages need two insured swords.
147	const takeDamagedItem = (
148	  insured: Item[],
149	  available: Item[],
150	  damage: Damage,
151	): { item: Item; remaining: Item[] } => {
152	  const index = available.findIndex((item) => item.type === damage.itemType);
153	  if (index === -1) {
154	    throw unmatchedDamageError(insured, damage.itemType);
155	  }
156	  return {
157	    item: available[index],
158	    remaining: available.filter((_, at) => at !== index),
159	  };
160	};
161	
162	// Each damage paired with the insured item it is settled against. Separated
163	// from the summing below because pairing and arithmetic are two rules: which
164	// item answers a damage is a matching question, what that pair pays is not.
165	// This is also where an unmatched damage is rejected, so payoutForDamages sees
166	// only pairs it can price.
167	interface SettledPair {
168	  item: Item;
169	  damage: Damage;
170	}
171	
172	const pairDamagesWithItems = (
173	  items: Item[],
174	  damages: Damage[],
175	): SettledPair[] =>
176	  damages.reduce<{ pairs: SettledPair[]; available: Item[] }>(
177	    ({ pairs, available }, damage) => {
178	      const { item, remaining } = takeDamagedItem(items, available, damage);
179	      return { pairs: [...pairs, { item, damage }], available: remaining };
180	    },
181	    { pairs: [], available: items },
182	  ).pairs;
183	
184	// A damage is a loss, never a gain: a negative amount would pay the MHPCO's
185	// own money back into the policy's cap, so the claim is rejected outright.
186	const rejectNegativeAmounts = (damages: Damage[]): void => {
187	  for (const { itemType, amount } of damages) {
188	    if (amount < 0) {
189	      throw claimRejection(
190	        `reports a negative ${itemType} damage of ${amount}`,
191	      );
192	    }
193	  }
194	};
195	
196	export const payoutForDamages = (items: Item[], damages: Damage[]): number => {
197	  rejectNegativeAmounts(damages);
198	  return pairDamagesWithItems(items, damages).reduce(
199	    (total, { item, damage }) => total + netOfDeductible(item, damage),
200	    0,
201	  );
202	};
203

1	// What a policy costs. This module answers one question — given the items on
2	// a policy and the context the policy is written in, what premium does the
3	// customer pay? It knows nothing about scenarios, steps, or the order events
4	// happen in; see claim-office.ts for that. What a policy pays OUT is the
5	// mirror question, answered by coverage.ts.
6	
7	import { roundUpInFavourOfMHPCO } from "./rounding.js";
8	import { quoteRejection } from "./rejection.js";
9	
10	export interface Customer {
11	  yearsWithMHPCO: number;
12	}
13	
14	const PROCESSING_FEE = 5;
15	const BASE_PREMIUM_BY_TYPE = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	} as const satisfies Record<string, number>;
23	
24	export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
25	
26	export interface Item {
27	  type: KnownItemType;
28	  material?: string;
29	  enchantment?: number;
30	  cursed?: boolean;
31	}
32	
33	const FIRST_INSURANCE_SURCHARGE = 0.1;
34	
35	// The MHPCO's price list is closed: an item whose type is absent from it has
36	// no premium and no insurance value, so the quote is refused rather than
37	// guessed at. The type reaches here from parsed JSON, so the compiler's
38	// KnownItemType narrowing is not enough on its own.
39	const basePremiumOf = (item: Item): number => {
40	  const basePremium: number | undefined = BASE_PREMIUM_BY_TYPE[item.type];
41	  if (basePremium === undefined) {
42	    throw quoteRejection(
43	      `names a ${item.type}, which the MHPCO does not insure`,
44	    );
45	  }
46	  return basePremium;
47	};
48	
49	const BLOCK_SIZE = 3;
50	const BLOCK_BASE_PREMIUM = 60;
51	
52	const groupByType = (items: Item[]): Item[][] => [
53	  ...items
54	    .reduce(
55	      (groups, item) =>
56	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
57	      new Map<KnownItemType, Item[]>(),
58	    )
59	    .values(),
60	];
61	
62	const sumOfBasePremiums = (items: Item[]): number =>
63	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
64	
65	// Exactly three alike components form a block at a reduced premium; any
66	// other count is priced per item.
67	//
68	// Deliberate simplification: "component" is not yet enforced, so three alike
69	// swords would also get the block. No test covers it and the spec gives no
70	// example — revisit when one does.
71	const groupBasePremiumOf = (group: Item[]): number =>
72	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(group);
73	
74	const policyBasePremiumOf = (items: Item[]): number =>
75	  groupByType(items).reduce((sum, group) => sum + groupBasePremiumOf(group), 0);
76	
77	const CURSE_SURCHARGE = 0.5;
78	
79	// Item-specific modifiers are charged as a percentage of the affected item's
80	// OWN base premium. See withPolicyWideModifiers for the other scope.
81	const shareOfOwnBasePremium = (item: Item, rate: number): number =>
82	  basePremiumOf(item) * rate;
83	
84	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
85	const HIGH_ENCHANTMENT_THRESHOLD = 5;
86	
87	const isHighlyEnchanted = (item: Item): boolean =>
88	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
89	
90	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
91	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
92	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
93	];
94	
95	// Every modifier rate in this domain combines additively, whether item-scoped
96	// or policy-wide: two rates of +50 % and +30 % make +80 %, never +95 %.
97	const combinedRate = (rates: number[]): number =>
98	  rates.reduce((total, rate) => total + rate, 0);
99	
100	// Both item modifiers can apply at once, and they stack additively: a cursed
101	// item with enchantment 5 pays 50 % + 30 % of its base premium.
102	const surchargeRateOn = (item: Item): number =>
103	  combinedRate(
104	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
105	      ({ rate }) => rate,
106	    ),
107	  );
108	
109	const surchargeOn = (item: Item): number =>
110	  shareOfOwnBasePremium(item, surchargeRateOn(item));
111	
112	const itemSurchargesOf = (items: Item[]): number =>
113	  items.reduce((sum, item) => sum + surchargeOn(item), 0);
114	
115	// Policy-wide modifiers scale the whole policy base premium, unlike item
116	// modifiers which are charged against the affected item's own base premium.
117	// They combine additively, so a policy carrying +10 % and -20 % pays 90 % of
118	// its base — not 110 % × 80 %.
119	const LOYALTY_DISCOUNT = -0.2;
120	const LOYALTY_THRESHOLD_YEARS = 2;
121	
122	const isLoyal = (customer: Customer): boolean =>
123	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
124	
125	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
126	
127	// Everything about the policy's context that shifts its rates, as opposed to
128	// the items being priced. Travels as one value because every policy-wide
129	// modifier reads from it.
130	export interface PolicyContext {
131	  customer: Customer;
132	  isFollowUpContract: boolean;
133	}
134	
135	const policyWideModifierRatesFor = ({
136	  customer,
137	  isFollowUpContract,
138	}: PolicyContext): number[] => [
139	  FIRST_INSURANCE_SURCHARGE,
140	  ...(isLoyal(customer) ? [LOYALTY_DISCOUNT] : []),
141	  ...(isFollowUpContract ? [FOLLOW_UP_CONTRACT_DISCOUNT] : []),
142	];
143	
144	const withPolicyWideModifiers = (
145	  policyBase: number,
146	  policy: PolicyContext,
147	): number =>
148	  policyBase * (1 + combinedRate(policyWideModifierRatesFor(policy)));
149	
150	export const premiumFor = (items: Item[], policy: PolicyContext): number =>
151	  roundUpInFavourOfMHPCO(
152	    withPolicyWideModifiers(policyBasePremiumOf(items), policy) +
153	      itemSurchargesOf(items) +
154	      PROCESSING_FEE,
155	  );
